mapper.insert:
insert into CHB_CONSIGNOR_DETAIL_SUB (REGIST_SEQNO, LAST_HOLD_DAY, PROD_ID, PROD_NAME, PRD_REGIST_CODE, MANAGER, PROD_TYPE, PROD_INVEST_TYPE, RAISE_TYPE, TERMID, PROD_SCALE, INBANK_BONDMARK_HOLD_DENOMINA, INBANK_BONDMARK_HOLD_RATIO, HOLDER_NAME, HOLDER_TYPE, INVEST_AMOUNT, INVEST_RATIO, TWO_HOLDER_NAME, TWO_HOLDER_TYPE, TWO_INVEST_AMOUNT, TWO_INVEST_RATIO, PROD_SHARE, HOLDER_SHARE, REMARK, STATUS, CHB_SUBMIT_DEADLINE, STATUS_DATE, SUBMIT_TIME, SUMIT_SEQ, SEND_STATUS, SUBMIT_FEEDBACK_STATUS, SUBMIT_FEEDBACK_MSG, CREATE_USER, ORG_CODE, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME ) SELECT A.REGIST_SEQNO,A.LAST_HOLD_DAY,A.PROD_ID, A.PROD_NAME,A.PRD_REGIST_CODE,A.MANAGER, A.PROD_TYPE,A.PROD_INVEST_TYPE,A.RAISE_TYPE, A.TERMID,A.PROD_SCALE,A.INBANK_BONDMARK_HOLD_DENOMINA, A.INBANK_BONDMARK_HOLD_RATIO,A.HOLDER_NAME, A.HOLDER_TYPE,A.INVEST_AMOUNT,A.INVEST_RATIO, A.TWO_HOLDER_NAME,A.TWO_HOLDER_TYPE,A.TWO_INVEST_AMOUNT, A.TWO_INVEST_RATIO, A.PROD_SHARE, A.HOLDER_SHARE, A.REMARK, A.STATUS, A.CHB_SUBMIT_DEADLINE, A.STATUS_DATE, A.SUBMIT_TIME, A.SUMIT_SEQ, A.SEND_STATUS, A.SUBMIT_FEEDBACK_STATUS, A.SUBMIT_FEEDBACK_MSG, A.CREATE_USER, A.ORG_CODE, A.CREATE_DEPT, A.CREATE_TIME, A.UPDATE_USER, A.UPDATE_TIME FROM (
SELECT #{item.registSeqno,jdbcType=VARCHAR} AS REGIST_SEQNO, #{item.lastHoldDay,jdbcType=DATE} AS LAST_HOLD_DAY, #{item.prodId,jdbcType=VARCHAR} AS PROD_ID, #{item.prodName,jdbcType=VARCHAR} AS PROD_NAME, #{item.prdRegistCode,jdbcType=VARCHAR} AS PRD_REGIST_CODE, #{item.manager,jdbcType=VARCHAR} AS MANAGER, #{item.prodType,jdbcType=VARCHAR} AS PROD_TYPE, #{item.prodInvestType,jdbcType=VARCHAR} AS PROD_INVEST_TYPE, #{item.raiseType,jdbcType=VARCHAR} AS RAISE_TYPE, #{item.termid,jdbcType=VARCHAR} AS TERMID, #{item.prodScale,jdbcType=DECIMAL} AS PROD_SCALE, #{item.inbankBondmarkHoldDenomina,jdbcType=DECIMAL} AS INBANK_BONDMARK_HOLD_DENOMINA, #{item.inbankBondmarkHoldRatio,jdbcType=DECIMAL} AS INBANK_BONDMARK_HOLD_RATIO, #{item.holderName,jdbcType=VARCHAR} AS HOLDER_NAME, #{item.holderType,jdbcType=VARCHAR} AS HOLDER_TYPE, #{item.investAmount,jdbcType=DECIMAL} AS INVEST_AMOUNT, #{item.investRatio,jdbcType=DECIMAL} AS INVEST_RATIO, #{item.twoHolderName,jdbcType=VARCHAR} AS TWO_HOLDER_NAME, #{item.twoHolderType,jdbcType=VARCHAR} AS TWO_HOLDER_TYPE, #{item.twoInvestAmount,jdbcType=DECIMAL} AS TWO_INVEST_AMOUNT, #{item.twoInvestRatio,jdbcType=DECIMAL} AS TWO_INVEST_RATIO, #{item.prodShare,jdbcType=DECIMAL} AS PROD_SHARE, #{item.holderShare,jdbcType=DECIMAL} AS HOLDER_SHARE, #{item.remark,jdbcType=VARCHAR} AS REMARK, #{item.status,jdbcType=VARCHAR} AS STATUS, #{item.chbSubmitDeadline,jdbcType=TIMESTAMP} AS CHB_SUBMIT_DEADLINE, #{item.statusDate,jdbcType=DATE} AS STATUS_DATE, #{item.submitTime,jdbcType=TIMESTAMP} AS SUBMIT_TIME, #{item.sumitSeq,jdbcType=VARCHAR} AS SUMIT_SEQ, #{item.sendStatus,jdbcType=VARCHAR} AS SEND_STATUS, #{item.submitFeedbackStatus,jdbcType=VARCHAR} AS SUBMIT_FEEDBACK_STATUS, #{item.submitFeedbackMsg,jdbcType=VARCHAR} AS SUBMIT_FEEDBACK_MSG, #{item.createUser,jdbcType=VARCHAR} AS CREATE_USER, #{item.orgCode,jdbcType=VARCHAR} AS ORG_CODE, #{item.createDept,jdbcType=VARCHAR} AS CREATE_DEPT, now() AS CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} AS UPDATE_USER, now() AS UPDATE_TIME FROM dual
) A
